from collections import deque
def f(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    # flood fill zeros from border; unreach zeros enclosed -> 2
    vis=[[False]*w for _ in range(h)]; q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==0 and not vis[i][j]: vis[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0 and not vis[i][j]: vis[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0 and not vis[ni][nj]: vis[ni][nj]=True; q.append((ni,nj))
    inter=[[i,j] for i in range(h) for j in range(w) if g[i][j]==0 and not vis[i][j]]
    if inter:
        for i,j in inter: out[i][j]=2
        cols=[j for i,j in inter]; r=min(i for i,j in inter)-1
        for j in range(0,max(cols)+1): out[r][j]=2
    return out
